//
// Statistical inference on backtest results.
//
// A backtest gives one number per strategy. Whether the gap between two of them
// means anything depends on how noisy that number is, which a single path cannot
// tell you. This module answers "is strategy A different from strategy B?" with
// an interval and a p-value rather than a point estimate.
//
// The comparison that matters most in this app is a strategy against its own
// equilibrium prior. The two are highly correlated -- they hold nearly the same
// portfolio -- and that correlation is exactly what makes a small gap measurable,
// so every test here works on the PAIRED returns, never on two separate summaries.
#pragma once

#if defined(__FAST_MATH__) || defined(_M_FP_FAST)
#error "built with fast-math (-ffast-math, /fp:fast), which changes floating-point results: this C++ matches Python only without it"
#endif

#include <cmath>
#include <algorithm>
#include <optional>
#include "qtrans_arrays.hpp"  // Eigen, plus NumPy semantics

namespace bl_inference {

// Declarations (so functions can call each other in any order).
long long default_block_length(long long T);
double _ann_mean(const qt::Vec& x, double fpy);
double _ann_sharpe(const qt::Vec& x, double fpy);
long long newey_west_lag(long long T);
qt::Mat hac_cov(const qt::Mat& Y, std::optional<long long> lag = std::nullopt);
std::optional<double> hit_rate_pvalue(std::optional<double> hit_rate, long long n_independent);

// =========================================================
// Stationary block bootstrap (Politis & Romano, 1994)
// =========================================================
/// Mean block length ~ T^(1/3), the rate-optimal order for variance
/// estimation. About 13 for eight years of daily data.
inline long long default_block_length(long long T) {
    return std::max(2LL, qt::to_int(std::nearbyint(std::pow(static_cast<double>(T), 1.0 / 3.0))));
}

inline double _ann_mean(const qt::Vec& x, double fpy) {
    return qt::mean(x) * fpy;
}

inline double _ann_sharpe(const qt::Vec& x, double fpy) {
    double sd = qt::std_(x, 1);
    return qt::where(sd > 0, qt::mean(x) / sd * std::sqrt(fpy), qt::nan);
}

// =========================================================
// Ledoit & Wolf (2008): robust test for a difference in Sharpe ratios
// =========================================================
/// Newey-West (1994) plug-in bandwidth, floor(4 (T/100)^(2/9)).
inline long long newey_west_lag(long long T) {
    return qt::to_int(std::floor(4.0 * std::pow(static_cast<double>(T) / 100.0, 2.0 / 9.0)));
}

/// Newey-West long-run covariance of the columns of Y (already demeaned).
inline qt::Mat hac_cov(const qt::Mat& Y, std::optional<long long> lag) {
    // Y = np.asarray(Y, dtype=float): already a float64 array, so NumPy returns it unchanged
    long long T = Y.rows();
    long long L = !lag.has_value() ? newey_west_lag(T) : qt::value(lag);
    qt::Mat S = qt::matmul(Y.transpose(), Y) / static_cast<double>(T);
    for (long long j = 1; j < qt::iadd(L, 1LL); ++j) {
        double w = 1.0 - static_cast<double>(j) / (static_cast<double>(L) + 1.0);  // Bartlett kernel
        qt::Mat G = qt::matmul(qt::block(Y, j, qt::none, qt::none, qt::none).transpose(), qt::block(Y, qt::none, -j, qt::none, qt::none)) / static_cast<double>(T);
        qt::broadcast_into(S, w * qt::broadcast(G, G.transpose(), qt::add_op{}), qt::add_op{});
    }
    return S;
}

// =========================================================
// Is a rule's hit rate better than chance?
// =========================================================
/// One-sided p-value for hit rate > 50%, normal approximation to the
/// binomial on the number of independent checks.
inline std::optional<double> hit_rate_pvalue(std::optional<double> hit_rate, long long n_independent) {
    if (!hit_rate.has_value() || !(n_independent != 0)) {
        return std::nullopt;
    }
    double z = (qt::value(hit_rate) - 0.5) / std::sqrt(0.25 / static_cast<double>(n_independent));
    return 0.5 * std::erfc(z / std::sqrt(2));
}

}  // namespace bl_inference
